from fig_helpers_g45 import table_fig, bars_fig, fig_shape, fig_flowchart, fig_food_chain


def _q(b, n, d, p, c, w, e, h='', fig=None):
    return make_q(f'KH4-B{b:02d}-{n:03d}', d, p, c, w, e, 'Khoa học 4', h, fig)


def get_lessons_part1():
    lessons = []

